    ctx.fillStyle = `rgba(${v + 40},${v + 10},${Math.max(8, v - 18)},${0.1 + random() * 0.3})`
    ctx.fillRect(random() * 512, random() * 512, 2 + random() * 22, 0.6 + random() * 1.4)
  }
  for (let i = 0; i < 34; i++) {
    const y = random() * 512
    ctx.strokeStyle = `rgba(28,14,6,${0.12 + random() * 0.26})`
