export function createHealthBar(name = '') {
  const canvas = document.createElement('canvas')
  canvas.width = 320
  canvas.height = 48
  const ctx = canvas.getContext('2d')
  const texture = new THREE.CanvasTexture(canvas)
  texture.colorSpace = THREE.SRGBColorSpace
  const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false, depthWrite: false })
  const sprite = new THREE.Sprite(material)
  sprite.scale.set(1.55, 0.2325, 1)
  sprite.renderOrder = 5
  function draw(ratio) {
    ctx.clearRect(0, 0, 320, 48)
    ctx.fillStyle = 'rgba(4,10,11,0.82)'
    ctx.fillRect(2, 2, 316, 44)
    ctx.strokeStyle = 'rgba(255,232,199,0.5)'
    ctx.lineWidth = 2
    ctx.strokeRect(2, 2, 316, 44)
    const grad = ctx.createLinearGradient(8, 0, 312, 0)
    grad.addColorStop(0, '#a62a22')
    grad.addColorStop(0.55, '#e1493c')
    grad.addColorStop(1, '#ff9b77')
    ctx.fillStyle = grad
    ctx.fillRect(8, 8, 304 * Math.max(0, Math.min(1, ratio)), 32)
    ctx.fillStyle = 'rgba(255,255,255,0.18)'
    ctx.fillRect(8, 8, 304 * Math.max(0, Math.min(1, ratio)), 9)
    ctx.font = '900 15px "Arial Black", "DejaVu Sans", sans-serif'
    ctx.fillStyle = '#ffebcd'
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText(name, 160, 24)
    texture.needsUpdate = true
  }
  draw(1)
  return { sprite, draw }
}

import * as THREE from 'three'
import { makeConcrete, makeNeon, makePoster, makeWall, makeWood } from './textures.js'

const TAU = Math.PI * 2

function mesh(parent, geometry, material, position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1]) {
  const item = new THREE.Mesh(geometry, material)
  item.position.set(...position)
  item.rotation.set(...rotation)
  item.scale.set(...scale)
  parent.add(item)
  return item
}

function chainLinkTexture() {
  const c = document.createElement('canvas')
  c.width = 128
  c.height = 128
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, 128, 128)
  ctx.strokeStyle = 'rgba(185, 202, 196, 0.72)'
  ctx.lineWidth = 2
  for (let i = -128; i < 256; i += 18) {
    ctx.beginPath()
    ctx.moveTo(i, 0)
    ctx.lineTo(i + 128, 128)
    ctx.stroke()
    ctx.beginPath()
    ctx.moveTo(i + 128, 0)
    ctx.lineTo(i, 128)
    ctx.stroke()
  }
  const texture = new THREE.CanvasTexture(c)
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping
  texture.repeat.set(8, 2)
  texture.colorSpace = THREE.SRGBColorSpace
  return texture
}

function flashTexture() {
  const c = document.createElement('canvas')
  c.width = 64
  c.height = 64
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32)
  g.addColorStop(0, 'rgba(255,255,240,1)')
  g.addColorStop(0.18, 'rgba(255,238,200,0.8)')
  g.addColorStop(0.55, 'rgba(255,200,120,0.18)')
  g.addColorStop(1, 'rgba(255,190,100,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 64, 64)
  return new THREE.CanvasTexture(c)
}

function graffitiTexture(text, color) {
  const c = document.createElement('canvas')
  c.width = 1024
  c.height = 512
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, 1024, 512)
  ctx.save()
  ctx.translate(512, 256)
  ctx.rotate(-0.06)
  ctx.font = '900 190px "Arial Black", Impact, "DejaVu Sans", sans-serif'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.lineJoin = 'round'
  ctx.lineWidth = 18
  ctx.strokeStyle = 'rgba(8,12,12,0.55)'
  ctx.strokeText(text, 0, 0)
  ctx.fillStyle = color
  ctx.fillText(text, 0, 0)
  ctx.globalAlpha = 0.32
  ctx.strokeStyle = 'rgba(255,255,255,0.3)'
  ctx.lineWidth = 4
  ctx.strokeText(text, 0, 0)
  ctx.restore()
  const texture = new THREE.CanvasTexture(c)
  texture.colorSpace = THREE.SRGBColorSpace
  return texture
}

export function createArena(scene) {
  const floorTexture = makeConcrete()
  const wallTexture = makeWall()
  const woodTexture = makeWood()
  const updateTasks = []

  scene.background = new THREE.Color('#071013')
  scene.fog = new THREE.FogExp2('#071013', 0.031)

  const hemi = new THREE.HemisphereLight('#5a7c86', '#1a0f08', 1.1)
  scene.add(hemi)
  scene.add(new THREE.AmbientLight('#223338', 0.7))

  const key = new THREE.DirectionalLight('#ffc48c', 2.8)
  key.position.set(5, 10, 7)
  key.castShadow = true
  key.shadow.mapSize.set(2048, 2048)
  key.shadow.camera.left = -9
  key.shadow.camera.right = 9
  key.shadow.camera.top = 9
  key.shadow.camera.bottom = -7
  key.shadow.camera.near = 1
  key.shadow.camera.far = 30
  key.shadow.bias = -0.0007
  key.shadow.normalBias = 0.025
  scene.add(key)

  const rim = new THREE.DirectionalLight('#55d8d1', 1.65)
  rim.position.set(-8, 6, -8)
  scene.add(rim)
  const warmRim = new THREE.DirectionalLight('#ff7c3d', 1.2)
  warmRim.position.set(8, 4, -5)
  scene.add(warmRim)

  // Floor.
  const floor = mesh(
    scene,
    new THREE.PlaneGeometry(64, 64),
    new THREE.MeshStandardMaterial({ map: floorTexture, color: '#b9c2bd', roughness: 0.78, metalness: 0.12 }),
    [0, 0, 0],
    [-Math.PI / 2, 0, 0],
  )
  floor.receiveShadow = true

  // Chalk fight circle, partially worn.
  const ring = mesh(
    scene,
    new THREE.RingGeometry(4.85, 5.02, 96),
    new THREE.MeshBasicMaterial({ color: '#ded5ba', transparent: true, opacity: 0.2, side: THREE.DoubleSide }),
    [0.2, 0.012, -0.3],
    [-Math.PI / 2, 0, 0],
  )
  ring.renderOrder = 1
  mesh(
    scene,
    new THREE.RingGeometry(0.55, 0.62, 48),
    new THREE.MeshBasicMaterial({ color: '#d7c8a4', transparent: true, opacity: 0.1, side: THREE.DoubleSide }),
    [0.2, 0.013, -0.3],
    [-Math.PI / 2, 0, 0],
  )

  // Grimy puddles.
  const puddleMat = new THREE.MeshPhysicalMaterial({
    color: '#10181a',
    roughness: 0.09,
    metalness: 0.62,
    clearcoat: 0.8,
    transparent: true,
    opacity: 0.68,
    side: THREE.DoubleSide,
  })
  for (const [x, z, s, r] of [
    [-3.1, 3.2, 1.3, 0.3],
    [2.3, 4.3, 0.9, -0.4],
    [5.1, 0.8, 1.4, 0.8],
    [-5.8, -1.7, 1.1, 0.2],
    [0.7, -3.5, 0.75, 0.6],
  ]) {
    const puddle = mesh(scene, new THREE.CircleGeometry(1, 28), puddleMat, [x, 0.015, z], [-Math.PI / 2, 0, r], [s, s * 0.55, 1])
    puddle.renderOrder = 2
  }

  // Back wall and side walls.
  const backWall = mesh(
    scene,
    new THREE.PlaneGeometry(44, 13),
    new THREE.MeshStandardMaterial({ map: wallTexture, color: '#929b98', roughness: 0.94 }),
    [0, 6.5, -9.5],
  )
  backWall.receiveShadow = true
  const leftWall = mesh(
    scene,
    new THREE.PlaneGeometry(30, 12),
    new THREE.MeshStandardMaterial({ map: wallTexture, color: '#87908d', roughness: 0.95 }),
    [-12.5, 6, 2],
    [0, Math.PI / 2, 0],
  )
  leftWall.receiveShadow = true
  const rightWall = mesh(
    scene,
    new THREE.PlaneGeometry(30, 12),
    new THREE.MeshStandardMaterial({ map: wallTexture, color: '#7d8784', roughness: 0.95 }),
    [12.5, 6, 2],
    [0, -Math.PI / 2, 0],
  )
  rightWall.receiveShadow = true

  // Concrete columns.
  for (const x of [-10.8, 10.8]) {
    const column = mesh(
      scene,
      new THREE.BoxGeometry(1.05, 12, 1.05),
      new THREE.MeshStandardMaterial({ map: wallTexture, color: '#757e7b', roughness: 0.96 }),
      [x, 6, -7.7],
    )
    column.castShadow = true
    column.receiveShadow = true
    mesh(scene, new THREE.BoxGeometry(1.35, 0.3, 1.35), new THREE.MeshStandardMaterial({ color: '#3a4140', roughness: 0.9 }), [x, 0.15, -7.7])
  }

  // Ceiling girders and ducts.
  const beamMat = new THREE.MeshStandardMaterial({ color: '#303a3b', roughness: 0.74, metalness: 0.55 })
  for (let i = 0; i < 5; i++) {
    mesh(scene, new THREE.BoxGeometry(26, 0.34, 0.4), beamMat, [0, 8.7 - i * 0.08, -7.2 + i * 3.3], [0, 0, 0])
  }
  for (const x of [-8.1, -2.9, 2.5, 7.9]) {
    mesh(scene, new THREE.BoxGeometry(0.26, 0.26, 20), beamMat, [x, 8.35, 1.2])
  }
  mesh(scene, new THREE.CylinderGeometry(0.32, 0.32, 19, 12), new THREE.MeshStandardMaterial({ color: '#4a5352', roughness: 0.72, metalness: 0.5 }), [-9.3, 7.9, 0.5], [Math.PI / 2, 0, 0])

  // Hanging chain, just for texture.
  const chainMat = new THREE.MeshStandardMaterial({ color: '#6f7774', metalness: 0.85, roughness: 0.45 })
  const chainCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(6.8, 8.5, -4.8),
    new THREE.Vector3(6.8, 5.6, -4.6),
    new THREE.Vector3(6.5, 3.8, -4.1),
  ])
  mesh(scene, new THREE.TubeGeometry(chainCurve, 16, 0.035, 6, false), chainMat)
  mesh(scene, new THREE.TorusGeometry(0.16, 0.035, 5, 12), chainMat, [6.5, 3.6, -4.1], [0.4, 0.2, 0])

  // Industrial lamps.
  const bulbMat = new THREE.MeshBasicMaterial({ color: '#ffd9a2' })
  const shadeMat = new THREE.MeshStandardMaterial({ color: '#28302f', roughness: 0.62, metalness: 0.7, side: THREE.DoubleSide })
  const lampPositions = [
    [-4.7, 6.7, 2.2, 1.0],
    [4.4, 6.9, -2.2, 0.85],
    [0.1, 7.5, -5.6, 0.7],
  ]
  const coneMat = new THREE.MeshBasicMaterial({
    color: '#ffc077',
    transparent: true,
    opacity: 0.055,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
  })
  for (const [x, y, z, seed] of lampPositions) {
    const lamp = new THREE.Group()
    lamp.position.set(x, y, z)
    scene.add(lamp)
    mesh(lamp, new THREE.CylinderGeometry(0.035, 0.035, 1.2, 6), chainMat, [0, 0.7, 0])
    mesh(lamp, new THREE.ConeGeometry(0.48, 0.44, 18, 1, true), shadeMat, [0, 0.15, 0], [0, 0, 0])
    mesh(lamp, new THREE.SphereGeometry(0.12, 12, 8), bulbMat, [0, 0.02, 0])
    const light = new THREE.PointLight('#ffb267', 22, 13, 1.8)
    light.position.set(0, -0.15, 0)
    lamp.add(light)
    // Fake volumetric cone.
    mesh(lamp, new THREE.ConeGeometry(2.15, 5.5, 28, 1, true), coneMat.clone(), [0, -2.75, 0], [Math.PI, 0, 0])
    updateTasks.push((t) => {
      light.intensity = 18 + Math.sin(t * 3.1 + seed * 7) * 1.2 + Math.sin(t * 13.7 + seed) * 0.5
    })
  }

  // Neon signs.
  const neonMat = new THREE.MeshBasicMaterial({ map: makeNeon('KAYISI', '#ff8e2f'), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.95 })
  const neon = mesh(scene, new THREE.PlaneGeometry(7.2, 2.25), neonMat, [0.3, 6.1, -9.43])
  neon.renderOrder = 3
  const neonLight = new THREE.PointLight('#ff791c', 34, 17, 2)
  neonLight.position.set(0.3, 5.7, -8.2)
  scene.add(neonLight)
  updateTasks.push((t) => {
    const flicker = Math.sin(t * 8.3) > 0.96 ? 0.25 : 1
    neonMat.opacity = (0.78 + Math.sin(t * 1.3) * 0.05) * flicker
    neonLight.intensity = 30 * flicker
  })

  const turkish = new THREE.MeshBasicMaterial({ map: makeNeon('DÖVÜŞ', '#55ded4'), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.7 })
  mesh(scene, new THREE.PlaneGeometry(3.6, 1.12), turkish, [-11.9, 5.9, -1.6], [0, Math.PI / 2, 0])
  const cyanLight = new THREE.PointLight('#3bd6cc', 18, 12, 2)
  cyanLight.position.set(-10.8, 5.2, -1.6)
  scene.add(cyanLight)

  // Posters and graffiti.
  const posterMat = new THREE.MeshStandardMaterial({ map: makePoster('KAYISI', 'RIPE FURY', '#e6dcc4'), roughness: 0.95 })
  mesh(scene, new THREE.PlaneGeometry(1.8, 2.7), posterMat, [-7.3, 4.4, -9.42])
  const poster2 = new THREE.MeshStandardMaterial({ map: makePoster('FIGHT', 'NO REFUNDS', '#d3cab2'), roughness: 0.95 })
  mesh(scene, new THREE.PlaneGeometry(1.6, 2.4), poster2, [8.9, 4.6, -9.42], [0, 0, 0.03])
  const graffiti = new THREE.MeshBasicMaterial({ map: graffitiTexture('ACIZ', '#d3a04a'), transparent: true, opacity: 0.42, depthWrite: false })
  mesh(scene, new THREE.PlaneGeometry(4.6, 2.3), graffiti, [5.4, 2.7, -9.4])
  const graffiti2 = new THREE.MeshBasicMaterial({ map: graffitiTexture('2016', '#be4b3c'), transparent: true, opacity: 0.3, depthWrite: false })
  mesh(scene, new THREE.PlaneGeometry(3.8, 1.9), graffiti2, [-4.6, 2.3, -9.4])

  // Wall pipes and vents.
  const pipeMat = new THREE.MeshStandardMaterial({ color: '#525d5b', roughness: 0.66, metalness: 0.62 })
  mesh(scene, new THREE.CylinderGeometry(0.14, 0.14, 12, 10), pipeMat, [-9.9, 5.2, -9.2], [0, 0, 0])
  mesh(scene, new THREE.CylinderGeometry(0.19, 0.19, 5, 10), pipeMat, [9.6, 3.6, -9.1], [0, 0, Math.PI / 2])
  mesh(scene, new THREE.BoxGeometry(1.5, 1.1, 0.2), new THREE.MeshStandardMaterial({ color: '#3b4544', roughness: 0.7, metalness: 0.5 }), [5.6, 7.2, -9.3])
  for (let i = 0; i < 6; i++) {
    mesh(scene, new THREE.BoxGeometry(1.3, 0.045, 0.04), new THREE.MeshStandardMaterial({ color: '#151c1c' }), [5.6, 6.8 + i * 0.14, -9.18])
  }

  // Chain-link fence panels, leaving the neon sign visible.
  const fenceTexture = chainLinkTexture()
  const fenceMat = new THREE.MeshBasicMaterial({
    map: fenceTexture,
    transparent: true,
    opacity: 0.4,
    alphaTest: 0.14,
    side: THREE.DoubleSide,
    color: '#9ca8a3',
    depthWrite: false,
  })
  const postMat = new THREE.MeshStandardMaterial({ color: '#38413f', metalness: 0.8, roughness: 0.55 })
  for (const [x, width] of [[-7.6, 7.2], [7.6, 7.2]]) {
    const fence = mesh(scene, new THREE.PlaneGeometry(width, 3.1), fenceMat, [x, 1.55, -7.3], [0, 0, 0])
    fence.renderOrder = 2
    for (const dx of [-width / 2, width / 2]) {
      mesh(scene, new THREE.CylinderGeometry(0.055, 0.055, 3.3, 8), postMat, [x + dx, 1.65, -7.3])
    }
    mesh(scene, new THREE.CylinderGeometry(0.04, 0.04, width, 8), postMat, [x, 3.13, -7.3], [0, 0, Math.PI / 2])
  }

  // Crowd silhouettes behind the fence.
  const crowdMat = new THREE.MeshStandardMaterial({ color: '#151d1e', roughness: 0.96 })
  const crowd = []
  for (let i = 0; i < 20; i++) {
    const person = new THREE.Group()
    const side = i % 2 === 0 ? -1 : 1
    person.position.set(side * (3.6 + Math.random() * 5.3), 0, -8.2 + Math.random() * 0.55)
    person.rotation.y = Math.PI + (Math.random() - 0.5) * 0.5
    const scale = 0.78 + Math.random() * 0.45
    person.scale.setScalar(scale)
    scene.add(person)
    mesh(person, new THREE.CapsuleGeometry(0.24, 0.72, 5, 10), crowdMat, [0, 1.0, 0])
    sphere(person, 0.16, crowdMat, [0, 1.6, 0])
    // Occasionally a tiny lit phone screen.
    if (Math.random() > 0.55) {
      mesh(person, new THREE.PlaneGeometry(0.09, 0.16), new THREE.MeshBasicMaterial({ color: Math.random() > 0.5 ? '#a7e5de' : '#ffe1a6' }), [0.18, 1.18, 0.2], [0, 0.3, 0])
    }
    person.userData.phase = Math.random() * TAU
    crowd.push(person)
  }

  // Camera flashes in the crowd.
  const flashTex = flashTexture()
  const flashes = []
  for (let i = 0; i < 8; i++) {
    const mat = new THREE.SpriteMaterial({ map: flashTex, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0 })
    const sprite = new THREE.Sprite(mat)
    sprite.position.set(-8 + Math.random() * 16, 1.5 + Math.random() * 1.4, -7.6 + Math.random() * 0.6)
    sprite.scale.setScalar(1.2)
    scene.add(sprite)
    sprite.userData = { phase: Math.random() * TAU, speed: 0.6 + Math.random() * 1.4 }
    flashes.push(sprite)
  }
  updateTasks.push((t) => {
    for (const sprite of flashes) {
      const p = sprite.userData.phase
      const pulse = Math.max(0, Math.sin(t * sprite.userData.speed * 2.1 + p) - 0.94) / 0.06
      sprite.material.opacity = pulse * 0.8
    }
  })

  // Props: barrels, crates, cones, papers, tires.
  const barrelColors = ['#5e2a1f', '#223d47', '#5d4a1e']
  for (const [x, z, i, r] of [
    [-5.3, -3.9, 0, 0.2],
    [5.9, -4.4, 1, -0.1],
    [-6.1, 3.8, 2, 0.5],
    [4.5, 4.3, 0, 0.9],
  ]) {
    const barrel = new THREE.Group()
    barrel.position.set(x, 0, z)
    barrel.rotation.y = r
    scene.add(barrel)
    const mat = new THREE.MeshStandardMaterial({ color: barrelColors[i], roughness: 0.68, metalness: 0.42 })
    mesh(barrel, new THREE.CylinderGeometry(0.34, 0.34, 0.86, 16), mat, [0, 0.43, 0])
    for (const y of [0.12, 0.43, 0.75]) {
      mesh(barrel, new THREE.TorusGeometry(0.345, 0.023, 5, 18), new THREE.MeshStandardMaterial({ color: '#262e2e', metalness: 0.8, roughness: 0.4 }), [0, y, 0], [Math.PI / 2, 0, 0])
    }
  }

  const crateMat = new THREE.MeshStandardMaterial({ map: woodTexture, color: '#8e795a', roughness: 0.9 })
  for (const [x, y, z, s, r] of [
    [6.6, 0.38, 2.7, 0.76, 0.2],
    [5.9, 0.38, 3.2, 0.66, -0.15],
    [6.25, 1.12, 2.95, 0.6, 0.5],
    [-7.4, 0.42, 1.9, 0.84, -0.3],
    [-6.7, 0.3, 1.2, 0.6, 0.1],
  ]) {
    const crate = mesh(scene, new THREE.BoxGeometry(s, s, s), crateMat, [x, y, z], [0, r, 0])
    crate.castShadow = true
    crate.receiveShadow = true
    // Slats.
    for (const side of [-1, 1]) {
      mesh(scene, new THREE.BoxGeometry(s * 1.02, s * 0.1, 0.02), new THREE.MeshStandardMaterial({ color: '#3c2d1d', roughness: 0.9 }), [x, y + side * s * 0.32, z + s / 2 + 0.005], [0, r, 0])
    }
  }

  const coneMat2 = new THREE.MeshStandardMaterial({ color: '#d85c1f', roughness: 0.7 })
  const cone = new THREE.Group()
  cone.position.set(-4.2, 0, 4.7)
  cone.rotation.y = 0.4
  scene.add(cone)
  mesh(cone, new THREE.ConeGeometry(0.23, 0.7, 12), coneMat2, [0, 0.38, 0])
  mesh(cone, new THREE.CylinderGeometry(0.12, 0.16, 0.1, 12), new THREE.MeshStandardMaterial({ color: '#eee5cf', roughness: 0.7 }), [0, 0.42, 0])
  mesh(cone, new THREE.BoxGeometry(0.48, 0.06, 0.48), new THREE.MeshStandardMaterial({ color: '#1b2220', roughness: 0.9 }), [0, 0.03, 0])

  const paperMat = new THREE.MeshStandardMaterial({ color: '#c1b9a3', roughness: 1, side: THREE.DoubleSide })
  for (let i = 0; i < 15; i++) {
    const paper = mesh(scene, new THREE.PlaneGeometry(0.26 + Math.random() * 0.22, 0.34 + Math.random() * 0.2), paperMat, [(Math.random() - 0.5) * 11, 0.018, (Math.random() - 0.5) * 9], [-Math.PI / 2, 0, Math.random() * TAU])
    paper.renderOrder = 1
  }

  const tireMat = new THREE.MeshStandardMaterial({ color: '#161a19', roughness: 0.92 })
  for (let i = 0; i < 3; i++) {
    mesh(scene, new THREE.TorusGeometry(0.42, 0.15, 10, 20), tireMat, [-8.4, 0.16 + i * 0.3, -2.4], [Math.PI / 2, 0, 0])
  }

  // Scattered glass glints.
  const glintMat = new THREE.MeshBasicMaterial({ color: '#9de8df', transparent: true, opacity: 0.4 })
  for (let i = 0; i < 24; i++) {
    mesh(scene, new THREE.PlaneGeometry(0.02 + Math.random() * 0.03, 0.02 + Math.random() * 0.03), glintMat, [(Math.random() - 0.5) * 10, 0.02, (Math.random() - 0.5) * 8], [-Math.PI / 2, 0, Math.random() * TAU])
  }

  // Dust motes.
  const dustCount = 700
  const dustPos = new Float32Array(dustCount * 3)
  const dustSeed = new Float32Array(dustCount)
  for (let i = 0; i < dustCount; i++) {
    dustPos[i * 3] = (Math.random() - 0.5) * 22
    dustPos[i * 3 + 1] = Math.random() * 7
    dustPos[i * 3 + 2] = (Math.random() - 0.5) * 17
    dustSeed[i] = Math.random() * TAU
  }
  const dustGeo = new THREE.BufferGeometry()
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3))
  const dustMat = new THREE.PointsMaterial({ color: '#ffd6a0', size: 0.025, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true })
  const dust = new THREE.Points(dustGeo, dustMat)
  scene.add(dust)

  const baseDust = dustPos.slice()
  updateTasks.push((t) => {
    const arr = dustGeo.attributes.position.array
    for (let i = 0; i < dustCount; i++) {
      const p = dustSeed[i]
      arr[i * 3] = baseDust[i * 3] + Math.sin(t * 0.24 + p) * 0.6
      arr[i * 3 + 1] = 0.15 + ((baseDust[i * 3 + 1] + t * 0.06 + p * 0.1) % 7)
      arr[i * 3 + 2] = baseDust[i * 3 + 2] + Math.cos(t * 0.2 + p) * 0.5
    }
    dustGeo.attributes.position.needsUpdate = true
    for (const person of crowd) {
      person.position.y = Math.sin(t * 1.5 + person.userData.phase) * 0.025
      person.rotation.z = Math.sin(t * 0.8 + person.userData.phase) * 0.018
    }
  })

  return {
    update(t) {
      for (const task of updateTasks) task(t)
    },
    key,
    neonLight,
  }
}

function sphere(parent, radius, material, position, segments = 12) {
  return mesh(parent, new THREE.SphereGeometry(radius, segments, Math.max(6, Math.round(segments * 0.7))), material, position)
}

import * as THREE from 'three'

function radialTexture(inner, outer, stops) {
  const c = document.createElement('canvas')
  c.width = 128
  c.height = 128
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64)
  for (const [offset, color] of stops) g.addColorStop(offset, color)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 128, 128)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

function ringTexture() {
  const c = document.createElement('canvas')
  c.width = 256
  c.height = 256
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, 256, 256)
  const g = ctx.createRadialGradient(128, 128, 76, 128, 128, 128)
  g.addColorStop(0, 'rgba(255,255,255,0)')
  g.addColorStop(0.62, 'rgba(255,255,255,0)')
  g.addColorStop(0.8, 'rgba(255,255,255,0.95)')
  g.addColorStop(0.92, 'rgba(255,190,110,0.2)')
  g.addColorStop(1, 'rgba(255,190,110,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 256, 256)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

function arcTexture() {
  const c = document.createElement('canvas')
  c.width = 256
  c.height = 256
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, 256, 256)
  ctx.translate(128, 128)
  ctx.strokeStyle = 'rgba(255,245,220,0.95)'
  ctx.lineWidth = 16
  ctx.lineCap = 'round'
  ctx.shadowColor = 'rgba(255,180,80,0.9)'
  ctx.shadowBlur = 25
  ctx.beginPath()
  ctx.arc(0, 0, 88, -1.05, 1.05)
  ctx.stroke()
  ctx.strokeStyle = 'rgba(255,170,70,0.5)'
  ctx.lineWidth = 36
  ctx.shadowBlur = 40
  ctx.beginPath()
  ctx.arc(0, 0, 88, -0.95, 0.95)
  ctx.stroke()
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

const PARTICLE_COLORS = {
  orange: '#ff9a37',
  gold: '#ffd37d',
  steel: '#d7e3e6',
  red: '#ff5b40',
  green: '#b8ed62',
  dust: '#b5a58a',
}

export class FX {
  constructor(scene, camera) {
    this.scene = scene
    this.camera = camera
    this.time = 0
    this.particles = []
    this.popups = []
    this.rings = []
    this.arcs = []
    this.ringTexture = ringTexture()
    this.arcTexture = arcTexture()

    const geometry = new THREE.TetrahedronGeometry(0.05)
    const mats = {}
    for (const [key, color] of Object.entries(PARTICLE_COLORS)) {
      mats[key] = new THREE.MeshBasicMaterial({ color, transparent: true })
    }
    for (let i = 0; i < 150; i++) {
      const m = new THREE.Mesh(geometry, mats.orange)
      m.visible = false
      m.frustumCulled = false
      scene.add(m)
      this.particles.push({ mesh: m, velocity: new THREE.Vector3(), life: 0, maxLife: 1, spin: new THREE.Vector3(), gravity: 1, baseScale: 1 })
    }
    this.mats = mats
    this.ringPool = []
    for (let i = 0; i < 8; i++) {
      const mat = new THREE.SpriteMaterial({ map: this.ringTexture, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0 })
      const sprite = new THREE.Sprite(mat)
      sprite.visible = false
      sprite.renderOrder = 4
      scene.add(sprite)
      this.ringPool.push({ sprite, life: 0, maxLife: 0.4, maxScale: 2 })
    }
    this.arcPool = []
    for (let i = 0; i < 6; i++) {
      const mat = new THREE.SpriteMaterial({ map: this.arcTexture, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0 })
      const sprite = new THREE.Sprite(mat)
      sprite.visible = false
      sprite.renderOrder = 4
      scene.add(sprite)
      this.arcPool.push({ sprite, life: 0, maxLife: 0.3 })
    }
  }

  burst(position, type = 'orange', count = 18, strength = 1) {
    let used = 0
    for (const p of this.particles) {
      if (p.life > 0) continue
      const mat = this.mats[type] || this.mats.orange
      p.mesh.material = mat
      p.mesh.visible = true
      p.mesh.position.copy(position)
      p.mesh.position.x += (Math.random() - 0.5) * 0.2
      p.mesh.position.y += (Math.random() - 0.5) * 0.2
      p.mesh.position.z += (Math.random() - 0.5) * 0.2
      const theta = Math.random() * Math.PI * 2
      const phi = Math.acos(2 * Math.random() - 1)
      const speed = (2.5 + Math.random() * 7) * strength
      p.velocity.set(Math.sin(phi) * Math.cos(theta), Math.abs(Math.cos(phi)) * 0.9 + 0.2, Math.sin(phi) * Math.sin(theta)).multiplyScalar(speed)
      p.baseScale = 0.6 + Math.random() * 1.2
      p.mesh.scale.setScalar(p.baseScale)
      p.spin.set(Math.random() * 12, Math.random() * 12, Math.random() * 12)
      p.maxLife = 0.35 + Math.random() * 0.55
      p.life = p.maxLife
      p.gravity = 12 + Math.random() * 8
      if (++used >= count) break
    }
  }

  shockwave(position, color = '#ffb15a', maxScale = 2.2) {
    const ring = this.ringPool.find((r) => r.life <= 0)
    if (!ring) return
    ring.sprite.visible = true
    ring.sprite.position.copy(position)
    ring.sprite.position.y += 0.1
    ring.sprite.material.color.set(color)
    ring.sprite.material.opacity = 0.85
    ring.sprite.scale.setScalar(0.2)
    ring.maxScale = maxScale
    ring.maxLife = 0.42
    ring.life = ring.maxLife
  }

  slash(position, color = '#ffe0af', rotation = 0, scale = 1.6) {
    const arc = this.arcPool.find((a) => a.life <= 0)
    if (!arc) return
    arc.sprite.visible = true
    arc.sprite.position.copy(position)
    arc.sprite.material.color.set(color)
    arc.sprite.material.rotation = rotation
    arc.sprite.material.opacity = 0.95
    arc.sprite.scale.setScalar(scale)
    arc.maxLife = 0.28
    arc.life = arc.maxLife
  }

  popup(text, position, { color = '#ffe9c7', outline = '#2b0c01', size = 1, life = 0.85, burst = false, rotation = 0 } = {}) {
    const canvas = document.createElement('canvas')
    const ctx = canvas.getContext('2d')
    const font = 900
    const fontSize = 90
    ctx.font = `${font} ${fontSize}px "Arial Black", Impact, "DejaVu Sans", sans-serif`
    const width = Math.max(260, ctx.measureText(text).width + 80)
    canvas.width = Math.ceil(width)
    canvas.height = 190
    const c = canvas.getContext('2d')
    if (burst) {
      c.save()
      c.translate(canvas.width / 2, 100)
      c.fillStyle = 'rgba(255,154,55,0.18)'
      c.beginPath()
      for (let i = 0; i < 24; i++) {
        const a = (i / 24) * Math.PI * 2
        const r = i % 2 === 0 ? 120 : 62
        c.lineTo(Math.cos(a) * r * 1.5, Math.sin(a) * r * 0.8)
      }
      c.closePath()
      c.fill()
      c.restore()
    }
    c.font = `${font} ${fontSize}px "Arial Black", Impact, "DejaVu Sans", sans-serif`
    c.textAlign = 'center'
    c.textBaseline = 'middle'
    c.lineJoin = 'round'
    c.lineWidth = 18
    c.strokeStyle = outline
    c.strokeText(text, canvas.width / 2, 100)
    c.lineWidth = 8
    c.strokeStyle = outline
    c.strokeText(text, canvas.width / 2, 100)
    c.fillStyle = color
    c.fillText(text, canvas.width / 2, 100)

    const texture = new THREE.CanvasTexture(canvas)
    texture.colorSpace = THREE.SRGBColorSpace
    const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false, depthWrite: false })
    const sprite = new THREE.Sprite(material)
    sprite.renderOrder = 8
    const worldHeight = 0.55 * size
    sprite.scale.set((canvas.width / canvas.height) * worldHeight, worldHeight, 1)
    sprite.position.copy(position)
    sprite.material.rotation = rotation
    this.scene.add(sprite)
    this.popups.push({
      sprite,
      life,
      maxLife: life,
      velocity: new THREE.Vector3((Math.random() - 0.5) * 0.5, 2.1 + Math.random() * 0.7, (Math.random() - 0.5) * 0.4),
      rotation,
    })
  }

  update(dt) {
    this.time += dt
    for (const p of this.particles) {
      if (p.life <= 0) continue
      p.life -= dt
      if (p.life <= 0) {
        p.mesh.visible = false
        continue
      }
      p.velocity.y -= p.gravity * dt
      p.mesh.position.addScaledVector(p.velocity, dt)
      if (p.mesh.position.y < 0.03) {
        p.mesh.position.y = 0.03
        p.velocity.y *= -0.32
        p.velocity.x *= 0.75
        p.velocity.z *= 0.75
      }
      p.mesh.rotation.x += p.spin.x * dt
      p.mesh.rotation.y += p.spin.y * dt
      p.mesh.rotation.z += p.spin.z * dt
      const k = Math.max(0, p.life / p.maxLife)
      p.mesh.scale.setScalar(p.baseScale * (0.45 + k * 0.75))
      p.mesh.material.opacity = Math.min(1, k * 2.2)
    }
    for (const ring of this.ringPool) {
      if (ring.life <= 0) continue
      ring.life -= dt
      if (ring.life <= 0) {
        ring.sprite.visible = false
        continue
      }
      const k = 1 - ring.life / ring.maxLife
      ring.sprite.scale.setScalar(0.2 + k * ring.maxScale)
      ring.sprite.material.opacity = (1 - k) * 0.85
      ring.sprite.position.y += dt * 0.15
    }
    for (const arc of this.arcPool) {
      if (arc.life <= 0) continue
      arc.life -= dt
      if (arc.life <= 0) {
        arc.sprite.visible = false
        continue
      }
      const k = 1 - arc.life / arc.maxLife
      arc.sprite.material.opacity = (1 - k) * 0.95
      arc.sprite.scale.setScalar(arc.sprite.scale.x + dt * 3.4)
    }
    for (let i = this.popups.length - 1; i >= 0; i--) {
      const pop = this.popups[i]
      pop.life -= dt
      if (pop.life <= 0) {
        this.scene.remove(pop.sprite)
        pop.sprite.material.map.dispose()
        pop.sprite.material.dispose()
        this.popups.splice(i, 1)
        continue
      }
      const k = pop.life / pop.maxLife
      pop.velocity.y -= 3.4 * dt
      pop.sprite.position.addScaledVector(pop.velocity, dt)
      pop.sprite.material.opacity = Math.min(1, k * 2.6)
      const popScale = 0.8 + (1 - k) * 0.28
      pop.sprite.scale.set(pop.sprite.scale.x * 0.999, pop.sprite.scale.y * 0.999, 1)
      pop.sprite.scale.multiplyScalar(1 + (1 - k) * 0.001)
      pop.sprite.material.rotation = pop.rotation + Math.sin(this.time * 5 + i) * 0.02
    }
  }
}

export class Sound {
  constructor() {
    this.ctx = null
    this.master = null
    this.noise = null
    this.ambient = null
    this.muted = false
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AudioCtx = window.AudioContext || window.webkitAudioContext
    if (!AudioCtx) return
    this.ctx = new AudioCtx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.55
    this.master.connect(this.ctx.destination)

    const length = this.ctx.sampleRate * 2
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
    this.noise = buffer

    this.startAmbience()
  }

  startAmbience() {
    if (!this.ctx || this.ambient) return
    const ctx = this.ctx
    const bed = ctx.createGain()
    bed.gain.value = 0.035
    bed.connect(this.master)

    // Low, grimy room tone.
    const osc = ctx.createOscillator()
    osc.type = 'sawtooth'
    osc.frequency.value = 43
    const lp = ctx.createBiquadFilter()
    lp.type = 'lowpass'
    lp.frequency.value = 120
    const g = ctx.createGain()
    g.gain.value = 0.5
    osc.connect(lp).connect(g).connect(bed)
    osc.start()

    const osc2 = ctx.createOscillator()
    osc2.type = 'sine'
    osc2.frequency.value = 86
    const g2 = ctx.createGain()
    g2.gain.value = 0.22
    osc2.connect(g2).connect(bed)
    osc2.start()

    // Distant crowd murmur.
    const src = ctx.createBufferSource()
    src.buffer = this.noise
    src.loop = true
    const band = ctx.createBiquadFilter()
    band.type = 'bandpass'
    band.frequency.value = 430
    band.Q.value = 0.55
    const crowdGain = ctx.createGain()
    crowdGain.gain.value = 0.26
    src.connect(band).connect(crowdGain).connect(bed)
    src.start()

    this.ambient = bed
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.04)
  }

  noiseBurst(duration = 0.2, { type = 'bandpass', frequency = 900, q = 0.8, gain = 0.2, slide = 0 } = {}) {
    if (!this.ctx || this.muted) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const src = ctx.createBufferSource()
    src.buffer = this.noise
    src.playbackRate.value = 0.8 + Math.random() * 0.4
    const filter = ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(frequency, now)
    if (slide) filter.frequency.exponentialRampToValueAtTime(Math.max(60, frequency + slide), now + duration)
    filter.Q.value = q
    const env = ctx.createGain()
    env.gain.setValueAtTime(0.0001, now)
    env.gain.exponentialRampToValueAtTime(gain, now + 0.012)
    env.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    src.connect(filter).connect(env).connect(this.master)
    src.start(now)
    src.stop(now + duration + 0.03)
  }

  tone(freq, endFreq, duration, { type = 'sine', gain = 0.2, delay = 0, filter = 0 } = {}) {
    if (!this.ctx || this.muted) return
    const ctx = this.ctx
    const now = ctx.currentTime + delay
    const osc = ctx.createOscillator()
    osc.type = type
    osc.frequency.setValueAtTime(freq, now)
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), now + duration)
    const env = ctx.createGain()
    env.gain.setValueAtTime(0.0001, now)
    env.gain.exponentialRampToValueAtTime(gain, now + 0.01)
    env.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    let node = osc
    if (filter) {
      const lp = ctx.createBiquadFilter()
      lp.type = 'lowpass'
      lp.frequency.value = filter
      node.connect(lp)
      node = lp
    }
    node.connect(env).connect(this.master)
    osc.start(now)
    osc.stop(now + duration + 0.03)
  }

  whoosh(strength = 1) {
    this.noiseBurst(0.18 + strength * 0.06, { frequency: 700 + strength * 350, q: 1.1, gain: 0.09 + strength * 0.03, slide: -450 })
  }

  impact(kind = 'fist', strength = 1) {
    this.tone(120 + Math.random() * 30, 38, 0.18 + strength * 0.05, { type: 'sine', gain: 0.24 + strength * 0.07 })
    this.noiseBurst(0.09, { type: 'highpass', frequency: 900, q: 0.5, gain: 0.16 })
    if (kind === 'metal') {
      this.tone(1180, 540, 0.22, { type: 'triangle', gain: 0.12 })
      this.tone(780, 310, 0.3, { type: 'square', gain: 0.055, delay: 0.01 })
    } else if (kind === 'wood') {
      this.tone(340, 120, 0.16, { type: 'square', gain: 0.09 })
      this.noiseBurst(0.1, { frequency: 420, q: 0.5, gain: 0.12 })
    } else if (kind === 'pan') {
      this.tone(940, 740, 0.32, { type: 'triangle', gain: 0.14 })
      this.tone(1320, 960, 0.24, { type: 'sine', gain: 0.08, delay: 0.005 })
    }
  }

  oof() {
    this.tone(210 + Math.random() * 60, 70, 0.28, { type: 'sawtooth', gain: 0.12, filter: 900 })
    this.noiseBurst(0.14, { frequency: 300, q: 0.6, gain: 0.08 })
  }

  hurt() {
    this.tone(90, 45, 0.3, { type: 'square', gain: 0.16, filter: 500 })
    this.noiseBurst(0.2, { frequency: 250, q: 0.4, gain: 0.12 })
  }

  cheer() {
    if (!this.ctx || this.muted) return
    this.noiseBurst(0.8, { type: 'bandpass', frequency: 800, q: 0.45, gain: 0.12 })
    this.tone(420, 620, 0.5, { type: 'sine', gain: 0.02 })
  }

  ko() {
    this.tone(220, 55, 0.9, { type: 'sawtooth', gain: 0.16, filter: 700 })
    this.noiseBurst(0.6, { frequency: 260, q: 0.4, gain: 0.1 })
  }

  start() {
    this.tone(70, 150, 0.22, { type: 'square', gain: 0.14, filter: 500 })
    this.cheer()
  }
}

