  .overlay { align-items: center; padding-top: max(10px, env(safe-area-inset-top)); }
  .intro h1 { font-size: clamp(56px, 14vh, 96px); }
  .intro h2 { font-size: 17px; }
  .tagline { margin: 6px auto 8px; }
  .intro-controls, .fineprint { display: none; }
  .round-box { bottom: calc(118px + env(safe-area-inset-bottom)); }
  .top-actions { bottom: calc(154px + env(safe-area-inset-bottom)); }
  .weapon-hud { bottom: calc(120px + env(safe-area-inset-bottom)); }
}

/* Phones held sideways: keep the fight clear of the HUD. */
@media (max-width: 900px) and (max-height: 540px) and (orientation: landscape) {
  .hud-top { gap: 5px; }
  .hero-card { max-width: 52vw; }
  .enemy-stack { max-width: 41vw; }
  .round-box {
    top: calc(66px + env(safe-area-inset-top));
    bottom: auto;
    left: 50%;
  }
