  .round-btn.attack .smash-word { font-size: 14px; }
  .round-btn.attack .smash-fist { width: 20px; height: 20px; }
  .round-btn.swap { width: 60px; height: 60px; }
  .round-btn.swap b { font-size: 9px; max-width: 48px; }
  .round-btn.swap span { font-size: 6px; }
}

